    ];
    jsFiles().forEach(function(path) {
        var src = file_read({ path: path });
        if (!src) return;
        patterns.forEach(function(re) {
            var m;
            while ((m = re.exec(src)) !== null) {
                seen++;
                if (m[1].indexOf('tracker') === -1 && m[1].indexOf('customParams') === -1) {
                    offenders.push(path + ': ' + m[0].substring(0, 100));
