function payloadList(parsed, options) {
    if (Array.isArray(parsed)) return parsed;
    if (!parsed) return [];
    // Hoist the pullRequests-array probe so the precedence branches below
    // stay single-condition (keeps cyclomatic complexity within the CRAP
    // threshold — gh-1258 ratchet).
    var prs = Array.isArray(parsed.pullRequests) ? parsed.pullRequests : null;
    if (prs !== null && options && options.preferPullRequests) return prs;
    if (Array.isArray(parsed.items)) return parsed.items;
    return prs || [];
}

